import{_ as n,a0 as p,w as r,s as u,I as s,x as e,a1 as i,A as l,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"使用 FVWM 自定義 Linux 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"使用 FVWM 自定義 Linux 桌面 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 FVWM 自定義 Linux 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 FVWM 自定義 Linux 桌面 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191210 Customize your Linux desktop with FVWM","title":"使用 FVWM 自定義 Linux 桌面","tag":"201912","desc":""},"relativePath":"201912/20191210 Customize your Linux desktop with FVWM.md","filePath":"[post].md"}'),d={name:"201912/20191210 Customize your Linux desktop with FVWM.md"};function f(m,t,M,g,x,V){const o=p("Link");return r(),u("div",null,[t[25]||(t[25]=s("h1",{id:"使用-fvwm-自定義-linux-桌面",tabindex:"-1"},[e("使用 FVWM 自定義 Linux 桌面 "),s("a",{class:"header-anchor",href:"#使用-fvwm-自定義-linux-桌面","aria-label":"Permalink to “使用 FVWM 自定義 Linux 桌面”"},"​")],-1)),t[26]||(t[26]=s("blockquote",null,[s("p",null,"本文是 24 天 Linux 桌面特別系列的一部分。如果你正在尋找輕巧、快速且簡單的 Linux 窗口管理器，那麼 FVWM 可以勝任。但是，如果你正在尋找可以深入、探索和魔改的窗口管理器，那麼 FVWM 是必須的。")],-1)),t[27]||(t[27]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/201912/25/062800dwh3yhfcpx3ggjxp.jpg",alt:""})],-1)),s("p",null,[i(o,{href:"http://www.fvwm.org/"},{default:l(()=>[...t[0]||(t[0]=[e("FVWM",-1)])]),_:1}),t[2]||(t[2]=e(" 窗口管理器最早脱胎於對 1993 年的 ",-1)),i(o,{href:"https://en.wikipedia.org/wiki/Twm"},{default:l(()=>[...t[1]||(t[1]=[e("TWM",-1)])]),_:1}),t[3]||(t[3]=e(" 的修改。經過幾年的迭代，誕生了一個可高度自定義的環境，它可以配置任何行為、動作或事件。它支持自定義鍵綁定、鼠標手勢、主題、腳本等。",-1))]),s("p",null,[t[5]||(t[5]=e("儘管 FVWM 在安裝後即可投入使用，但默認分發版本僅提供了極其少的配置。這是開始自定義桌面環境的良好基礎，但是，如果你只想將其用作桌面，那麼可能要安裝由其它用户發佈的完整配置版本。FVWM 有幾種不同的分發版，包括模仿 Windows 95 的 FVWM95（至少在外觀和佈局上）。我嘗試了 ",-1)),i(o,{href:"https://www.box-look.org/p/1018270/"},{default:l(()=>[...t[4]||(t[4]=[e("FVWM-Crystal",-1)])]),_:1}),t[6]||(t[6]=e("，這是一個具有一些現代 Linux 桌面約定的現代主題。",-1))]),s("p",null,[t[8]||(t[8]=e("可以從 Linux 發行版的軟件倉庫中安裝要嘗試的 FVWM 分發版。如果找不到特定的 FVWM 分發版，那麼可以安裝基礎的 FVWM2 包，然後進入 ",-1)),i(o,{href:"http://box-look.org"},{default:l(()=>[...t[7]||(t[7]=[e("Box-Look.org",-1)])]),_:1}),t[9]||(t[9]=e(" 手動下載主題包。這樣就需要更多的工作，但比從頭開始構建要少。",-1))]),t[28]||(t[28]=a('<p>安裝後，請註銷當前的桌面會話，以便你可以登錄 FVWM。默認情況下，會話管理器（KDM、GDM、LightDM 或 XDM，取決於你的設置）將繼續登錄到以前的桌面，因此你必須在登錄之前覆蓋該桌面。</p><p>對於 GDM：</p><p><img src="https://opensource.com/sites/default/files/advent-gdm_0.jpg" alt="Select your desktop session in GDM" title="Select your desktop session in GDM"></p><p>對於 KDM：</p><p><img src="https://opensource.com/sites/default/files/advent-kdm.jpg" alt="Select your desktop session with KDM" title="Select your desktop session with KDM"></p><h3 id="fvwm-桌面" tabindex="-1">FVWM 桌面 <a class="header-anchor" href="#fvwm-桌面" aria-label="Permalink to “FVWM 桌面”">​</a></h3><p>無論你使用什麼主題和配置，當你在桌面上單擊鼠標左鍵時，FVWM 至少會顯示一個菜單。菜單的內容取決於你所安裝的內容。FVWM-Crystal 分發版中的菜單包含對常用首選項的快速訪問，例如屏幕分辨率、壁紙設置、窗口裝飾等。</p><p>同 FVWM 中的幾乎所有東西一樣，你可以編輯菜單中你要想的內容，但 FVWM-Crystal 的特色在於其應用菜單欄。應用菜單位於屏幕的左上角，每個圖標都包含了相關的應用啓動器的菜單。例如，GIMP 圖標表示圖像編輯器，KDevelop 圖標表示集成開發環境（IDE），GNU 圖標表示文本編輯器，等等，具體取決於你在系統上安裝的程序。</p><p><img src="https://opensource.com/sites/default/files/advent-fvwm-crystal.jpg" alt="FVWM-crystal running on Slackware 14.2" title="FVWM-crystal running on Slackware 14.2"></p><p>FVWM-Crystal 還提供了虛擬桌面、任務欄、時鐘和應用欄。</p><p>關於背景，你可以使用與 FVWM-Crystal 捆綁在一起的壁紙，也可以使用 <code>feh</code> 命令設置自己的壁紙（你可能需要從倉庫中安裝它）。此命令有一些設置背景的選項，包括 <code>--bg-scale</code> 使用你選擇的圖片縮放填充屏幕，<code>--bg-fill</code> 直接填充而不縮放圖片，等等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ feh --bg-scale ~/Pictures/wallpapers/mybackground.jpg</span></span></code></pre></div><p>大多數配置文件都包含在 <code>$HOME/.fvwm-crystal</code> 中，某些系統範圍的默認文件位於 <code>/usr/share/fvwm-crystal</code>。</p><h3 id="自己嘗試一下" tabindex="-1">自己嘗試一下 <a class="header-anchor" href="#自己嘗試一下" aria-label="Permalink to “自己嘗試一下”">​</a></h3><p>FVWM 是大多作為一個桌面構建平台，它也是窗口管理器。它不會為你做到面面俱到，它期望你來配置儘可能的一切。</p><p>如果你正在尋找輕巧、快速且簡單的窗口管理器，那麼 FVWM 可以勝任。但是，如果你正在尋找可以深入、探索和魔改的窗口管理器，那麼 FVWM 是必須的。</p><hr>',17)),s("p",null,[t[11]||(t[11]=e("via: ",-1)),i(o,{href:"https://opensource.com/article/19/12/fvwm-linux-desktop"},{default:l(()=>[...t[10]||(t[10]=[e("https://opensource.com/article/19/12/fvwm-linux-desktop",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=e("作者：",-1)),i(o,{href:"https://opensource.com/users/seth"},{default:l(()=>[...t[12]||(t[12]=[e("Seth Kenlon",-1)])]),_:1}),t[17]||(t[17]=e(" 選題：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[13]||(t[13]=[e("lujun9972",-1)])]),_:1}),t[18]||(t[18]=e(" 譯者：",-1)),i(o,{href:"https://github.com/geekpi"},{default:l(()=>[...t[14]||(t[14]=[e("geekpi",-1)])]),_:1}),t[19]||(t[19]=e(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:l(()=>[...t[15]||(t[15]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=e("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[20]||(t[20]=[e("LCTT",-1)])]),_:1}),t[23]||(t[23]=e(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:l(()=>[...t[21]||(t[21]=[e("Linux中國",-1)])]),_:1}),t[24]||(t[24]=e(" 榮譽推出",-1))])])}const w=n(d,[["render",f]]);export{F as __pageData,w as default};
